#!/bin/sh
# Print the three most frequent client IPs, breaking equal counts by log order.
awk '
    NF {
        ip = $1
        if (!(ip in count))
            first[ip] = NR
        count[ip]++
    }
    END {
        for (rank = 1; rank <= 3; rank++) {
            best = ""
            best_count = -1
            best_first = 0

            for (ip in count) {
                if (selected[ip])
                    continue
                if (count[ip] > best_count ||
                    (count[ip] == best_count && (best == "" || first[ip] < best_first))) {
                    best = ip
                    best_count = count[ip]
                    best_first = first[ip]
                }
            }

            if (best == "")
                break
            print best
            selected[best] = 1
        }
    }
' access.log
